{"file_path": "singleton_demo.cpp", "new_string": "/**
 * ============================================================
 * C++ 单例模式（Singleton Pattern）完整实现
 * ============================================================
 * 
 * 本文件展示了三种线程安全的单例实现方式：
 * 1. 饿汉式（Eager Initialization）- 程序启动时即创建
 * 2. 双重检查锁（Double-Checked Locking）- 延迟初始化 + 锁优化
 * 3. Meyers Singleton（C++11 Magic Statics）- 推荐方式
 * 
 * 编译要求: C++11 或更高标准
 * 编译命令: g++ -std=c++11 -pthread -o singleton_demo singleton_demo.cpp
 * ============================================================
 */

#include <iostream>
#include <mutex>
#include <thread>
#include <vector>
#include <string>
#include <atomic>

// ============================================================
// 方式一：饿汉式单例（Eager Initialization）
// ============================================================
// 特点：
//   - 程序启动时（main函数之前）就创建实例
//   - 利用静态变量在程序加载时初始化的特性
//   - 天然线程安全（由操作系统保证静态变量初始化的线程安全性）
//   - 缺点：无论是否使用，都会占用内存；无法延迟初始化
//
// 适用场景：
//   - 单例对象创建开销小
//   - 程序运行期间一定会使用该单例
// ============================================================

class EagerSingleton {
public:
    // 获取单例实例的唯一接口
    static EagerSingleton& getInstance() {
        return instance_;
    }

    // 示例业务方法
    void doSomething(const std::string& caller) {
        std::cout << "[" << caller << "] EagerSingleton::doSomething() called, "
                  << "address = " << this << std::endl;
    }

    // 删除拷贝构造和赋值运算符，防止复制
    EagerSingleton(const EagerSingleton&) = delete;
    EagerSingleton& operator=(const EagerSingleton&) = delete;

    // 删除移动构造和赋值运算符
    EagerSingleton(EagerSingleton&&) = delete;
    EagerSingleton& operator=(EagerSingleton&&) = delete;

private:
    // 私有构造函数，禁止外部创建
    EagerSingleton() {
        std::cout << "[EagerSingleton] Constructor called (program startup)" << std::endl;
    }

    ~EagerSingleton() {
        std::cout << "[EagerSingleton] Destructor called" << std::endl;
    }

    // 静态成员变量，程序启动时即初始化
    static EagerSingleton instance_;
};

// 在类外定义并初始化静态成员（程序启动时执行）
EagerSingleton EagerSingleton::instance_;


// ============================================================
// 方式二：双重检查锁单例（Double-Checked Locking, DCLP）
// ============================================================
// 特点：
//   - 延迟初始化，只在第一次使用时创建
//   - 使用互斥锁保证线程安全
//   - 双重检查避免每次调用都加锁，优化性能
//   - 必须使用 std::atomic 保证内存可见性（C++11）
//
// 注意事项：
//   - C++11 之前，DCLP 在多线程环境下可能存在问题
//   - C++11 引入了内存模型和原子操作，可以正确实现
//   - 实现相对复杂，容易出错
//
// 适用场景：
//   - 需要延迟初始化
//   - 对性能要求较高
// ============================================================

class DCLPSingleton {
public:
    // 获取单例实例的唯一接口
    static DCLPSingleton* getInstance() {
        // 第一次检查：无锁快速路径
        DCLPSingleton* tmp = instance_.load(std::memory_order_acquire);
        if (tmp == nullptr) {
            std::lock_guard<std::mutex> lock(mutex_);
            // 第二次检查：加锁后再次确认
            tmp = instance_.load(std::memory_order_relaxed);
            if (tmp == nullptr) {
                tmp = new DCLPSingleton();
                instance_.store(tmp, std::memory_order_release);
                std::cout << "[DCLPSingleton] Instance created (lazy initialization)" << std::endl;
            }
        }
        return tmp;
    }

    // 示例业务方法
    void doSomething(const std::string& caller) {
        std::cout << "[" << caller << "] DCLPSingleton::doSomething() called, "
                  << "address = " << this << std::endl;
    }

    // 删除拷贝构造和赋值运算符
    DCLPSingleton(const DCLPSingleton&) = delete;
    DCLPSingleton& operator=(const DCLPSingleton&) = delete;
    DCLPSingleton(DCLPSingleton&&) = delete;
    DCLPSingleton& operator=(DCLPSingleton&&) = delete;

private:
    DCLPSingleton() {
        std::cout << "[DCLPSingleton] Constructor called" << std::endl;
    }

    ~DCLPSingleton() {
        std::cout << "[DCLPSingleton] Destructor called" << std::endl;
    }

    // 使用原子指针，保证多线程下的内存可见性
    static std::atomic<DCLPSingleton*> instance_;
    static std::mutex mutex_;
};

// 静态成员初始化
std::atomic<DCLPSingleton*> DCLPSingleton::instance_{nullptr};
std::mutex DCLPSingleton::mutex_;


// ============================================================
// 方式三：Meyers Singleton（C++11 Magic Statics）★ 推荐方式
// ============================================================
// 特点：
//   - 利用 C++11 的线程安全局部静态变量特性（§6.7 [stmt.dcl]）
//   - 代码简洁，天然线程安全
//   - 延迟初始化（第一次调用时才创建）
//   - 由编译器保证线程安全，无需手动加锁
//   - 保证在程序结束时自动销毁（析构函数会被调用）
//
// C++11 标准保证：
//   "If control enters the declaration concurrently while the variable 
//    is being initialized, the concurrent execution shall wait for 
//    the completion of the initialization."
//
// 适用场景：
//   - 绝大多数单例需求的首选方案
//   - 简洁、安全、高效
// ============================================================

class MeyersSingleton {
public:
    // 获取单例实例的唯一接口
    // C++11 保证：函数内局部静态变量的初始化是线程安全的
    static MeyersSingleton& getInstance() {
        // 第一次调用时初始化，之后直接返回引用
        static MeyersSingleton instance;
        return instance;
    }

    // 示例业务方法
    void doSomething(const std::string& caller) {
        std::cout << "[" << caller << "] MeyersSingleton::doSomething() called, "
                  << "address = " << this << std::endl;
    }

    // 删除拷贝构造和赋值运算符
    MeyersSingleton(const MeyersSingleton&) = delete;
    MeyersSingleton& operator=(const MeyersSingleton&) = delete;
    MeyersSingleton(MeyersSingleton&&) = delete;
    MeyersSingleton& operator=(MeyersSingleton&&) = delete;

private:
    MeyersSingleton() {
        std::cout << "[MeyersSingleton] Constructor called (lazy initialization)" << std::endl;
    }

    ~MeyersSingleton() {
        std::cout << "[MeyersSingleton] Destructor called" << std::endl;
    }
};


// ============================================================
// 通用单例模板类（可复用）
// ============================================================
// 特点：
//   - 基于 Meyers Singleton 实现的泛型模板
//   - 使用 CRTP（Curiously Recurring Template Pattern）
//   - 任何类只需继承此模板即可成为单例
//
// 使用方式：
//   class MyClass : public Singleton<MyClass> {
//       friend class Singleton<MyClass>;  // 允许基类访问私有构造
//   private:
//       MyClass() = default;
//   };
// ============================================================

template <typename T>
class Singleton {
public:
    static T& getInstance() {
        static T instance;
        return instance;
    }

    // 禁止拷贝和移动
    Singleton(const Singleton&) = delete;
    Singleton& operator=(const Singleton&) = delete;
    Singleton(Singleton&&) = delete;
    Singleton& operator=(Singleton&&) = delete;

protected:
    Singleton() = default;
    virtual ~Singleton() = default;
};

// 使用模板的示例类
class DatabaseConnection : public Singleton<DatabaseConnection> {
    friend class Singleton<DatabaseConnection>;  // 允许基类调用私有构造

public:
    void query(const std::string& sql) {
        std::cout << "[DatabaseConnection] Executing query: " << sql 
                  << ", address = " << this << std::endl;
    }

private:
    DatabaseConnection() {
        std::cout << "[DatabaseConnection] Connected to database" << std::endl;
    }

    ~DatabaseConnection() {
        std::cout << "[DatabaseConnection] Disconnected from database" << std::endl;
    }
};


// ============================================================
// 辅助函数：模拟多线程环境
// ============================================================

void threadFuncEager(const std::string& threadName) {
    EagerSingleton::getInstance().doSomething(threadName);
}

void threadFuncDCLP(const std::string& threadName) {
    DCLPSingleton::getInstance()->doSomething(threadName);
}

void threadFuncMeyers(const std::string& threadName) {
    MeyersSingleton::getInstance().doSomething(threadName);
}

void threadFuncDB(const std::string& threadName) {
    DatabaseConnection::getInstance().query("SELECT * FROM users");
}


// ============================================================
// 主函数：演示各种单例的使用
// ============================================================

int main() {
    std::cout << "========================================" << std::endl;
    std::cout << "  C++ 单例模式演示" << std::endl;
    std::cout << "========================================\n" << std::endl;

    // ----- 1. 饿汉式单例演示 -----
    std::cout << "--- 1. Eager Singleton ---" << std::endl;
    std::cout << "(Instance already created at program startup)\n" << std::endl;

    EagerSingleton& eager1 = EagerSingleton::getInstance();
    EagerSingleton& eager2 = EagerSingleton::getInstance();
    eager1.doSomething("Main");

    // 验证是同一个实例
    std::cout << "Same instance? " << (&eager1 == &eager2 ? "YES" : "NO") << "\n" << std::endl;

    // 多线程测试
    {
        std::vector<std::thread> threads;
        for (int i = 0; i < 4; ++i) {
            threads.emplace_back(threadFuncEager, "Thread-" + std::to_string(i));
        }
        for (auto& t : threads) t.join();
    }

    std::cout << std::endl;

    // ----- 2. 双重检查锁单例演示 -----
    std::cout << "--- 2. Double-Checked Locking Singleton ---" << std::endl;

    // 多线程同时获取实例
    {
        std::vector<std::thread> threads;
        for (int i = 0; i < 4; ++i) {
            threads.emplace_back(threadFuncDCLP, "Thread-" + std::to_string(i));
        }
        for (auto& t : threads) t.join();
    }

    // 验证是同一个实例
    DCLPSingleton* dclp1 = DCLPSingleton::getInstance();
    DCLPSingleton* dclp2 = DCLPSingleton::getInstance();
    std::cout << "\nSame instance? " << (dclp1 == dclp2 ? "YES" : "NO") << "\n" << std::endl;

    // ----- 3. Meyers Singleton 演示 -----
    std::cout << "--- 3. Meyers Singleton (Recommended) ---" << std::endl;

    // 多线程同时获取实例
    {
        std::vector<std::thread> threads;
        for (int i = 0; i < 4; ++i) {
            threads.emplace_back(threadFuncMeyers, "Thread-" + std::to_string(i));
        }
        for (auto& t : threads) t.join();
    }

    // 验证是同一个实例
    MeyersSingleton& meyers1 = MeyersSingleton::getInstance();
    MeyersSingleton& meyers2 = MeyersSingleton::getInstance();
    std::cout << "\nSame instance? " << (&meyers1 == &meyers2 ? "YES" : "NO") << "\n" << std::endl;

    // ----- 4. 通用模板单例演示 -----
    std::cout << "--- 4. Generic Singleton Template ---" << std::endl;

    // 多线程同时使用数据库连接
    {
        std::vector<std::thread> threads;
        for (int i = 0; i < 4; ++i) {
            threads.emplace_back(threadFuncDB, "Thread-" + std::to_string(i));
        }
        for (auto& t : threads) t.join();
    }

    // 验证是同一个实例
    DatabaseConnection& db1 = DatabaseConnection::getInstance();
    DatabaseConnection& db2 = DatabaseConnection::getInstance();
    std::cout << "\nSame instance? " << (&db1 == &db2 ? "YES" : "NO") << std::endl;

    std::cout << "\n========================================" << std::endl;
    std::cout << "  Demo completed. Destructors will be" << std::endl;
    std::cout << "  called automatically at program exit." << std::endl;
    std::cout << "========================================" << std::endl;

    return 0;
}"}
